using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BMFinish {
 const string A="Assets/Afrer_Seconds/05.Model/",E=A+"Environment/B2/";static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_FullFloor/";static Scene Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");return s;}
 static GameObject Put(string name,string path,Transform parent,Vector3 pos,float yaw){var src=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!src)throw new Exception("Missing "+path);var g=(GameObject)PrefabUtility.InstantiatePrefab(src,parent);g.name=name;g.transform.localPosition=pos;g.transform.localRotation=Quaternion.Euler(0,yaw,0);return g;}
 public static object Safety(){var s=Check();var root=s.GetRootGameObjects().Single(g=>g.name=="B2_MachineryNetwork").transform;var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));int count=0;foreach(var r in plan["rooms"].Where(r=>(string)r["kind"]!="core"&&(string)r["id"]!="C02")){string id=(string)r["id"];var parent=root.Find("B2_"+id+"_Sector/Equipment");if(parent.Find("B2_"+id+"_CCTV"))throw new Exception("Already detailed");float rad=(float)r["r"],angle=0;float best=-1000;for(int a=0;a<360;a+=3){float clear=r["doors"].Min(d=>Mathf.Abs(Mathf.DeltaAngle(a,(float)d["angle"])));if(clear<Mathf.Asin(3.25f/rad)*Mathf.Rad2Deg)continue;var p=new Vector3(Mathf.Cos(a*Mathf.Deg2Rad),0,Mathf.Sin(a*Mathf.Deg2Rad))*(Mathf.Sqrt(rad*rad-2.13f*2.13f)-.2f);float dist=plan["zones"].Where(q=>(string)q["room"]==id).Select(q=>Vector2.Distance(new Vector2(p.x,p.z),new Vector2((float)q["center"][0],(float)q["center"][1]))-Mathf.Max((float)q["size"][0],(float)q["size"][1])*.5f).DefaultIfEmpty(10).Min();float score=dist-clear*.003f;if(score>best){best=score;angle=a;}}
 var dir=new Vector3(Mathf.Cos(angle*Mathf.Deg2Rad),0,Mathf.Sin(angle*Mathf.Deg2Rad));float yaw=Quaternion.LookRotation(-dir).eulerAngles.y;var fire=Put("B2_"+id+"_WallSafety",rad==11?A+"Props/B2/BC_WallSafety_R11.fbx":A+"Props/B4/BP_WallSafety_R"+(int)rad+".fbx",parent,dir*(Mathf.Sqrt(rad*rad-2.13f*2.13f)-.2f),yaw);var bc=fire.AddComponent<BoxCollider>();bc.center=new Vector3(0,1.10f,.20f);bc.size=new Vector3(1.34f,1.75f,.42f);var mount=Put("B2_"+id+"_CCTVWallMount",A+"Environment/B3/BS_CCTVWallMount_R"+(int)rad+".fbx",parent,dir*(Mathf.Sqrt(rad*rad-3.65f*3.65f)-.16f),yaw);var camera=Put("B2_"+id+"_CCTV",A+"Enemy/CCTV_SecurityCamera_Articulated.prefab",parent,Vector3.zero,yaw);camera.transform.position=mount.transform.TransformPoint(new Vector3(0,3.287f,.49f));foreach(var t in new[]{fire.transform,mount.transform,camera.transform})PrefabUtility.RecordPrefabInstancePropertyModifications(t);count++;}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{wallSafety=count,cctv=count};}
 public static object LodPlan(){var s=Check();var root=s.GetRootGameObjects().Single(g=>g.name=="B2_MachineryNetwork");var groups=root.GetComponentsInChildren<MeshRenderer>().Where(r=>r.GetComponent<MeshFilter>()&&r.GetComponent<MeshFilter>().sharedMesh&&r.GetComponent<MeshFilter>().sharedMesh.isReadable&&!r.GetComponentInParent<LODGroup>()).GroupBy(r=>r.GetComponent<MeshFilter>().sharedMesh);var list=new List<object>();int n=0;foreach(var group in groups){var m=group.Key;string path=AssetDatabase.GetAssetPath(m);int tri=m.triangles.Length/3;if(tri<6000||path.Contains("_Shell")||path.Contains("_Lining")||path.Contains("_Floor")||path.Contains("BM_Surface"))continue;list.Add(new{name="BM_Lod_"+(++n).ToString("00"),asset=path,mesh=m.name,tri,materials=group.First().sharedMaterials.Select(AssetDatabase.GetAssetPath).ToArray(),renderers=group.Select(r=>GlobalObjectId.GetGlobalObjectIdSlow(r).ToString()).ToArray()});}File.WriteAllText(H+"lod_plan.json",JsonConvert.SerializeObject(list,Formatting.Indented));return new{meshes=n};}
 public static object Probes(){var s=Check();var root=s.GetRootGameObjects().Single(g=>g.name=="B2_MachineryNetwork").transform;if(root.Find("StaticReflections"))throw new Exception("Already baked");var parent=new GameObject("StaticReflections");parent.transform.SetParent(root,false);var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool on=player.activeSelf;player.SetActive(false);int count=0;try{var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));var data=new List<(string,Vector3,Vector3)>();foreach(var r in plan["rooms"].Where(r=>(string)r["id"]!="C02")){float rad=(float)r["r"];data.Add(((string)r["id"],new Vector3((float)r["x"],2,-(float)r["v"]),new Vector3(rad*2,rad+2,rad*2)));}foreach(var t in plan["tunnels"]){var ps=t["path"].Select(p=>new Vector3((float)p[0],0,-(float)p[1])).ToArray();var b=new Bounds(ps[0],Vector3.zero);foreach(var p in ps)b.Encapsulate(p);data.Add((((string)t["id"]).Replace("B2-",""),b.center+Vector3.up*1.7f,new Vector3(b.size.x+4.6f,4,b.size.z+4.6f)));}foreach(var row in data){var g=new GameObject("B2_Reflection_"+row.Item1);g.transform.SetParent(parent.transform,false);g.transform.localPosition=row.Item2;var p=g.AddComponent<ReflectionProbe>();p.size=row.Item3;p.center=Vector3.zero;p.blendDistance=1.2f;p.resolution=128;p.hdr=true;p.boxProjection=true;p.mode=ReflectionProbeMode.Custom;p.renderDynamicObjects=true;p.clearFlags=ReflectionProbeClearFlags.SolidColor;p.backgroundColor=new Color(.035f,.04f,.05f);p.intensity=.8f;string path=E+"Textures/BM_Reflection_"+row.Item1+".exr";if(!Lightmapping.BakeReflectionProbe(p,path))throw new Exception("Bake failed "+row.Item1);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Cubemap>(path);count++;}}finally{player.SetActive(on);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{probes=count};}
 public static object Occlusion(){var s=Check();foreach(var root in s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")))foreach(var r in root.GetComponentsInChildren<MeshRenderer>()){var flags=StaticEditorFlags.BatchingStatic|StaticEditorFlags.OccludeeStatic;if(r.GetComponent<MeshCollider>())flags|=StaticEditorFlags.OccluderStatic;GameObjectUtility.SetStaticEditorFlags(r.gameObject,flags);}StaticOcclusionCulling.smallestOccluder=2;StaticOcclusionCulling.smallestHole=.25f;StaticOcclusionCulling.backfaceThreshold=100;EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);bool started=StaticOcclusionCulling.Compute();return new{started};}
